const RAPIDAPI_KEY = "cec1f7f099msh19d57fb7bd65106p1d4040jsne632a37c958b";
const HOST = "forex-factory-scraper1.p.rapidapi.com";
const TIMEZONE = "GMT-06:00 Central Time (US & Canada)";

const body = $input.first().json.body || $input.first().json || {};
const dates = Array.isArray(body.dates) ? body.dates : [];
if (dates.length === 0) {
  return [{ json: { error: "No dates provided. POST { dates: [\"YYYY-MM-DD\", ...] }" } }];
}

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

const results = {};
for (const d of dates) {
  const [y, m, day] = d.split("-").map(Number);
  const url = `https://${HOST}/get_calendar_details?year=${y}&month=${m}&day=${day}&currency=USD&event_name=ALL&timezone=${encodeURIComponent(TIMEZONE)}&time_format=12h`;
  let attempt = 0;
  let done = false;
  while (!done && attempt < 2) {
    attempt++;
    try {
      const response = await this.helpers.httpRequest({
        method: "GET",
        url,
        headers: { "x-rapidapi-host": HOST, "x-rapidapi-key": RAPIDAPI_KEY },
        json: true,
        timeout: 4000,
      });
      results[d] = Array.isArray(response) ? response : [];
      done = true;
    } catch (err) {
      const msg = String((err && err.message) || err);
      if (/unexpected end of json|no data|204/i.test(msg)) {
        results[d] = [];
        done = true;
      } else if (/429/.test(msg) && attempt < 2) {
        await sleep(3000);
        continue;
      } else if (/timeout/i.test(msg)) {
        results[d] = { __timeout: true };
        done = true;
      } else {
        results[d] = { __fetch_error: msg };
        done = true;
      }
    }
  }
  await sleep(1500);
}

return [{ json: { results, dates_requested: dates.length, dates_returned: Object.keys(results).length } }];

